import sys

def main():
    low, high = map(int, sys.stdin.read().split())
    res = []
    if low <= 0 <= high:
        res.append(0)
    cur = list(range(1, 10))
    while cur:
        nxt = []
        for v in cur:
            if v > high:
                continue
            if v >= low:
                res.append(v)
            d = v % 10
            if d > 0:
                nxt.append(v * 10 + d - 1)
            if d < 9:
                nxt.append(v * 10 + d + 1)
        cur = nxt
    res.sort()
    print(' '.join(map(str, res)) if res else -1)

